const clamp = (value: number, min: number, max: number) => Math.min(max, Math.max(min, value))

function shiftLightness(lightness: number, delta: number) {
  const next = lightness + delta
  if (next > 95 || next < 8) return clamp(lightness - delta, 8, 95)
  return next
}

/** The extension's harmony recipe; the default rng keeps output deterministic. */
export function harmonyHexes(baseHex: string, harmony: Harmony, rng: () => number = () => 0.5) {
  const base = rgbToHsl(hexToRgb(baseHex))
  const jitter = (amount: number) => (rng() - 0.5) * 2 * amount
  return RECIPES[harmony].map(([hue, sat, light], index) => {
    if (index === 0) return baseHex
    return rgbToHex(
      hslToRgb({
        h: (base.h + hue + jitter(6) + 360) % 360,
        s: clamp(base.s + sat + jitter(6), 0, 100),
        l: shiftLightness(base.l, light + jitter(5)),
      }),
    )
  })
}

/** A fixed seed stands in for Math.random so the demo replays the same regenerate. */
function seeded(seed: number) {
  let state = seed
  return () => {
    state = (state + 0x6d2b79f5) | 0
    let t = Math.imul(state ^ (state >>> 15), 1 | state)
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
}

const HUE_BINS: readonly [number, string][] = [
  [10, 'Red'],
  [38, 'Orange'],
  [50, 'Amber'],
  [64, 'Yellow'],
  [85, 'Lime'],
  [150, 'Green'],
  [175, 'Teal'],
  [195, 'Cyan'],
  [210, 'Sky'],
  [240, 'Blue'],
  [255, 'Indigo'],
  [275, 'Violet'],
  [295, 'Purple'],
  [322, 'Magenta'],
  [345, 'Pink'],
  [360, 'Red'],
]

export function colorName(hex: string) {
  const { h, s, l } = rgbToHsl(hexToRgb(hex))
  if (l >= 96) return 'White'
  if (l <= 7) return 'Black'
  if (s < 10) return l > 70 ? 'Light Gray' : l < 30 ? 'Dark Gray' : 'Gray'
  const hue = HUE_BINS.find(([max]) => h < max)?.[1] ?? 'Red'
  const tone =
    l > 82
      ? 'Pale'
      : l > 66
        ? 'Light'
        : l < 22
          ? 'Deep'
          : l < 36
            ? 'Dark'
            : s < 35
              ? 'Muted'
              : s > 80 && l >= 40 && l <= 62
                ? 'Vivid'
                : null
  return tone ? `${tone} ${hue}` : hue
}

export const LIGHT_TEXT = '#ffffff'
export const DARK_TEXT = '#0a0a0a'

export function textOn(hex: string) {
  const light = contrast(hex, LIGHT_TEXT).ratio
  const dark = contrast(hex, DARK_TEXT).ratio
  return light >= dark ? LIGHT_TEXT : DARK_TEXT
}

export const SCALE_STEPS = [50, 100, 200, 300, 400, 500, 600, 700, 800, 900, 950] as const
const SCALE_LIGHTNESS = [0.97, 0.932, 0.882, 0.809, 0.707, 0.623, 0.546, 0.488, 0.424, 0.379, 0.282]
const SCALE_CHROMA = [0.06, 0.13, 0.24, 0.43, 0.67, 0.87, 1, 0.99, 0.81, 0.6, 0.37]

/** A 50–950 OKLCH ramp; the source colour replaces its nearest step. */
export function buildScale(hex: string) {
  const source = rgbToOklch(hexToRgb(hex))
  let nearest = 0
  SCALE_LIGHTNESS.forEach((target, index) => {
    if (Math.abs(target - source.l) < Math.abs(SCALE_LIGHTNESS[nearest] - source.l)) nearest = index
  })
  const peak = source.c * Math.min(1 / SCALE_CHROMA[nearest], 1.6)
  return SCALE_STEPS.map((step, index) => ({
    step,
    isBase: index === nearest,
    hex:
      index === nearest
        ? hex
        : rgbToHex(
            oklchToRgb({ l: SCALE_LIGHTNESS[index], c: peak * SCALE_CHROMA[index], h: source.h }),
          ),
  }))
}

const trim = (value: number, digits: number) => Number(value.toFixed(digits)).toString()

/** The Inspect rows: HEX, RGB, HSL and OKLCH in the extension's syntax. */
export function formatValues(hex: string) {
  const rgb = hexToRgb(hex)
  const { h, s, l } = rgbToHsl(rgb)
  const ok = rgbToOklch(rgb)
  return [
    { label: 'HEX', value: rgbToHex(rgb) },
    { label: 'RGB', value: `rgb(${rgb.r} ${rgb.g} ${rgb.b})` },
    { label: 'HSL', value: `hsl(${h} ${s}% ${l}%)` },
    { label: 'OKLCH', value: `oklch(${trim(ok.l * 100, 1)}% ${trim(ok.c, 3)} ${trim(ok.h, 1)})` },
  ]
}

