export function contrastSummary(hexes: string[], min = 4.5) {
  const foregrounds = [...hexes, LIGHT_TEXT, DARK_TEXT]
  let passing = 0
  let total = 0
  hexes.forEach((bg, row) => {
    foregrounds.forEach((fg, column) => {
      if (column === row) return
      total += 1
      if (contrast(fg, bg).ratio >= min) passing += 1
    })
  })
  return { passing, total }
}
export const CONTRAST = contrastSummary(REGENERATED)

